const float ECL_U_MAX = 1.9500000;
const int ECL_N = 40;
const float ECL_K = 0.78500000;
const vec3 ECL_A = vec3(0.67128000, 0.62432000, 0.55975000);
const vec3 ECL_C = vec3(0.23052000, 0.26345000, 0.30873000);
const vec3 ECL_LOG2[40] = vec3[40](
  vec3(-16.211000, -18.297000, -23.837000),
  vec3(-16.150000, -18.213000, -23.605000),
  vec3(-15.945000, -17.906000, -22.997000),
  vec3(-15.667000, -17.506000, -22.260000),
  vec3(-15.327000, -17.029000, -21.427000),
  vec3(-14.977000, -16.551000, -20.606000),
  vec3(-14.614000, -16.057000, -19.770000),
  vec3(-14.258000, -15.571000, -18.943000),
  vec3(-13.903000, -15.085000, -18.105000),
  vec3(-13.505000, -14.534000, -17.119000),
  vec3(-13.162000, -14.063000, -16.329000),
  vec3(-12.892000, -13.689000, -15.697000),
