float marchH(vec2 uv, int lmin, float lodG) {
  float acc = 0.0, rem = 1.0;
  for (int l = 0; l < 3; l++) {
    if (l < lmin) continue;
    Tile t = tileAt(uv, l);
    if (t.layer >= 0.0 && t.a > 0.0) {
      acc += rem * t.a * tileH(t, vec2(0.0));
      rem *= 1.0 - t.a;
      if (rem < 1e-3) return acc;
