// Angle between two vectors, well conditioned when it is small.
float eclAngle(vec3 a, vec3 b) { return atan(length(cross(a, b)), dot(a, b)); }

// Overlap area of discs of radii r1, r2 with centres d apart (planar).
float eclOverlap(float r1, float r2, float d) {
  if (d >= r1 + r2) return 0.0;
  float rm = min(r1, r2);
  if (d <= abs(r1 - r2)) return PI * rm * rm;
  float a1 = acos(clamp((d * d + r1 * r1 - r2 * r2) / (2.0 * d * r1), -1.0, 1.0));
  float a2 = acos(clamp((d * d + r2 * r2 - r1 * r1) / (2.0 * d * r2), -1.0, 1.0));
  return r1 * r1 * (a1 - sin(a1) * cos(a1)) + r2 * r2 * (a2 - sin(a2) * cos(a2));
}

// Share of the limb-darkened Sun (two discs) that a disc of radius occR
// centred sep from the Sun's centre leaves uncovered, per channel.
vec3 eclSunUncovered(float theta, float occR, float sep) {
  float full1 = PI * theta * theta, full2 = PI * ECL_K * ECL_K * theta * theta;
  float open1 = max(0.0, full1 - eclOverlap(theta, occR, sep));
  float open2 = max(0.0, full2 - eclOverlap(ECL_K * theta, occR, sep));
  return (ECL_A * open1 + ECL_C * open2) / (ECL_A * full1 + ECL_C * full2);
}

vec3 earthShadowOnMoonParts(vec3 p, vec3 sunPos, vec3 earthPos, out vec3 refracted) {
  refracted = vec3(0.0);
  vec3 sv = sunPos - p, ev = earthPos - p;
  float dSun = length(sv) * ECL_MOON_R_KM, dE = length(ev) * ECL_MOON_R_KM;
  float theta = asin(ECL_SUN_R_KM / dSun);
  float rho0 = asin(ECL_EARTH_R_KM / dE);
  float rhoA = asin((ECL_EARTH_R_KM + ECL_TOP_KM) / dE);
  float sep = eclAngle(sv, ev);
  float u = sep / (rho0 - theta);
  if (sep >= rhoA + theta && u >= ECL_U_MAX) return vec3(1.0);
  if (u < ECL_U_MAX) {
    float x = max(u, 0.0) / ECL_U_MAX * float(ECL_N - 1);
    int i = min(int(floor(x)), ECL_N - 2);
    float t = x - float(i);
    vec3 l = mix(ECL_LOG2[i], ECL_LOG2[i + 1], t);
    vec3 k = mix(ECL_EXP[i], ECL_EXP[i + 1], t);
    refracted = exp2(l + k * log2(dE / ECL_D0_KM));
  }
  return eclSunUncovered(theta, rhoA, sep);
}

vec3 earthShadowOnMoon(vec3 p, vec3 sunPos, vec3 earthPos) {
  vec3 r;
  vec3 d = earthShadowOnMoonParts(p, sunPos, earthPos, r);
  return d + r;
}

vec3 moonShadowOnEarth(vec3 p, vec3 sunPos, vec3 moonPos) {
  vec3 sv = sunPos - p, mv = moonPos - p;
  float theta = asin(ECL_SUN_R_KM / (length(sv) * ECL_MOON_R_KM));
  float rhoM = asin(1.0 / length(mv));
  float sep = eclAngle(sv, mv);
  if (sep >= rhoM + theta) return vec3(1.0);
  return eclSunUncovered(theta, rhoM, sep);
}


uniform sampler2D uLmShadow;
uniform mat4 uLmShadowM;
uniform float uLmShadowOn;
const float LM_RANGE = 199.0;
const float LM_TEXEL_M = 0.029297;
const float LM_BIAS = 0.0002944;
float lmShadeAt(vec3 P, vec3 nrm) {
  if (uLmShadowOn <= 0.0) return 1.0;
  vec4 sc = uLmShadowM * vec4(P + nrm * 0.02, 1.0);
  vec3 sp = sc.xyz / sc.w * 0.5 + 0.5;
  if (sp.x <= 0.0 || sp.x >= 1.0 || sp.y <= 0.0 || sp.y >= 1.0 || sp.z <= 0.0 || sp.z >= 0.999) return 1.0;
  vec2 ts = 1.0 / vec2(textureSize(uLmShadow, 0));
  // LM_TEXEL_M and LM_BIAS are written for LM_SHADOW_RES; a class with a smaller map has proportionally larger texels (and a larger two-texel bias).
  float lmK = 2048.0 * ts.x;
  float lmTexelM = LM_TEXEL_M * lmK;
  float lmBias = LM_BIAS * lmK;
  float rot = fract(sin(dot(P.xy, vec2(12.9898, 78.233))) * 43758.5453) * 6.2831853;
  float sumD = 0.0, nb = 0.0;
  for (int i = 0; i < 16; i++) {
    float a = float(i) * 2.399963 + rot;
    vec2 o = vec2(cos(a), sin(a)) * sqrt((float(i) + 0.5) / 16.0) * 10.0;
    float dm = texture(uLmShadow, sp.xy + o * ts).r;
    // dm > 0: a texel the depth pass never wrote reads 0 (an unwritten map) and would shade the whole ground; only a written texel can occlude.
    if (dm > 0.0 && dm < sp.z - lmBias) { sumD += (sp.z - dm) * LM_RANGE; nb += 1.0; }
  }
  if (nb < 0.5) return 1.0;
  float rTex = clamp(SUN_RAD * (sumD / nb) / lmTexelM, 0.7, 12.0);
  float occ = 0.0;
  for (int i = 0; i < 32; i++) {
    float a = float(i) * 2.399963 + rot;
    vec2 o = vec2(cos(a), sin(a)) * sqrt((float(i) + 0.5) / 32.0) * rTex;
    float dm = texture(uLmShadow, sp.xy + o * ts).r;
    occ += (dm > 0.0 && dm < sp.z - lmBias) ? 1.0 : 0.0;
  }
  return 1.0 - occ / 32.0;
}



out vec4 fragColor;
uniform vec3 uPads[4];          // footpad centres in the frame (metres); w below is the contact shadow's radius
uniform float uPadR;
uniform float uPadOn;
void main() {
  vec2 ndc = gl_FragCoord.xy / uResolution * 2.0 - 1.0;
  float aspect = uResolution.x / uResolution.y;
  vec3 d = normalize(uGRight * (ndc.x * uGTanHalf * aspect) + uGUp * (ndc.y * uGTanHalf) - uGBack);
  GHit g = groundHit(uGCam, d);
  if (g.cover <= 0.0) discard;

  float cover = g.cover;
  vec3 P = uGCam + d * g.t;
  float fpM = max(g.t, 0.05) * uTanPerPx;
  // A ray that missed shades the ground beneath its closest approach.
  if (!g.hit) P.z = terrainZ(P.xy, fpM);
  vec3 V = normalize(uGCam - P);
  vec2 mEN = P.xy + uGOff;
  vec2 sl = groundSlope(mEN, fpM) - P.xy / uGR;
  vec3 nrm = normalize(vec3(-sl.x, -sl.y, 1.0));
  float mu = max(dot(nrm, V), 0.0);
  float muG = max(abs(dot(V, vec3(0.0, 0.0, 1.0))), 0.15);
  fpM /= muG;
  vec2 uv = uGUv0 + P.xy * uGDuv;
