  float acc = 0.0, rem = 1.0;
  for (int l = 0; l < 3; l++) {
    if (l < lmin) continue;
    Tile t = tileAt(uv, l);
    if (t.layer >= 0.0 && t.a > 0.0) {
      acc += rem * t.a * tileH(t, vec2(0.0));
      rem *= 1.0 - t.a;
      if (rem < 1e-3) return acc;
    }
  }
  return acc + rem * heightAt(uv, lodG);
}


uniform highp sampler2D uPH0;
uniform highp sampler2D uPR0;
uniform float uPHOffset0;
 uniform vec4 uPG0;
uniform vec4 uPA0;
uniform vec2 uPS0;
uniform vec3 uPSite;            // the site, unit, Moon body frame
uniform vec3 uPEast;            // its local east and north, unit
uniform vec3 uPNorth;
uniform float uPatchBlend;      // 0: patch off
uniform float uPatchGround;     // 1: the patch's heights also make the ground (shadow march, ground hit); 0: they shade the surface only (Apollo 11)
uniform float uPH0M;            // heights are stored minus this (metres)
uniform float uSurround;        // 1: modelled surround (?surround=1): a statistically matched texture where no photograph reaches
uniform float uPSlopeMax;       // steepest slope (rise over run) a patch's heights may give; a step in the model (a seam) would otherwise read as a wall
// Per level i: uPG = grid (left edge east (m), top edge north (m), texel east (m), texel north (m)),
// uPA = the metres-to-texels matrix (column, row) = (a.x d.e + a.y d.n, a.z d.e + a.w d.n), uPS = size in texels.
const float PR_M = 1737400.0;

vec2 patchQ(vec4 g, vec4 a, vec2 m) { vec2 d = m - g.xy; return vec2(a.x * d.x + a.y * d.y, a.z * d.x + a.w * d.y); }
// 0 at the rectangle's edge, 1 more than fadeM inside it.
float patchEdge(vec2 q, vec2 size, vec4 g, float fadeM) {
  vec2 d = min(q, size - q) * vec2(g.z, g.w);
  float t = clamp(min(d.x, d.y) / max(fadeM, 1e-6), 0.0, 1.0);
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}
// A height is .r + .g: a two-part half float raster carries its remainder in .g, a one-part one has .g = 0.
float patchHeightOne(highp sampler2D H, vec2 q, vec2 size) {
  vec2 t = textureLod(H, q / size, 0.0).rg;
  return t.r + t.g;
}
// East and north slopes (rise over run) of a level's heights, one texel either side.
vec2 patchSlope(highp sampler2D H, vec2 q, vec2 size, vec4 g) {
  vec2 uv = q / size;
  vec2 e = 1.0 / size;
  vec2 tE = textureLod(H, uv + vec2(e.x, 0.0), 0.0).rg, tW = textureLod(H, uv - vec2(e.x, 0.0), 0.0).rg;
  vec2 tN = textureLod(H, uv - vec2(0.0, e.y), 0.0).rg, tS = textureLod(H, uv + vec2(0.0, e.y), 0.0).rg;
  float hE = tE.r + tE.g, hW = tW.r + tW.g, hN = tN.r + tN.g, hS = tS.r + tS.g;
  vec2 sl = vec2((hE - hW) / (2.0 * g.z), (hN - hS) / (2.0 * g.w));
  float m = length(sl);
  return m > uPSlopeMax ? sl * (uPSlopeMax / m) : sl;
}
// log2 of the image detail ratio, filtered over a pixel of fpM metres.
float patchDetail(highp sampler2D T, vec2 q, vec2 size, vec4 g, float fpM) {
  vec2 uv = q / size;
  vec2 gx = vec2(fpM / (g.z * size.x), 0.0), gy = vec2(0.0, fpM / (g.w * size.y));
  return (textureGrad(T, uv, gx, gy).r * 255.0 - 128.0) / 40.0;
}
// Value noise on the site's tangent plane (metres) for the modelled surround.
float surrHash(vec2 i) { return fract(sin(dot(i, vec2(127.1, 311.7))) * 43758.5453); }
float surrNoise(vec2 x) {
  vec2 i = floor(x), f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(surrHash(i), surrHash(i + vec2(1.0, 0.0)), f.x), mix(surrHash(i + vec2(0.0, 1.0)), surrHash(i + vec2(1.0, 1.0)), f.x), f.y) * 2.0 - 1.0;
}
// Metres east and north of the site of a body-frame unit vector x.
vec2 patchEN(vec3 x) {
  vec3 bP = vec3(dot(x, uX), dot(x, uY), dot(x, uK)) - uPSite;
  return vec2(dot(bP, uPEast), dot(bP, uPNorth)) * PR_M;
}
// Coverage of the coarsest height level at x (0 outside it, 1 more than its fade inside).
float patchCoverAt(vec3 x) {
  if (uPatchBlend * uPatchGround <= 0.0) return 0.0;
  vec2 mEN = patchEN(x);
  vec2 q = patchQ(uPG0, uPA0, mEN);
  return patchEdge(q, uPS0, uPG0, 40.0) * uPatchBlend * uPatchGround;
}
// The ground height (metres) at x: the coarsest patch heights over the tiles' (base, computed only where
// the patch does not fully cover), each finer level over the last. fpM is the pixel's footprint on
// the ground (0 for a shadow march sample): a level whose texel is 4 to 16 times smaller than the footprint
// fades out, so a far view is not sampled at 8 m and left to alias. Every level blends by its own edge fade, so the
// surface has no step where a level ends.
float patchGround(vec3 x, float fpM, int lmin, float lodG, float forTerrain) {
  vec2 mEN = patchEN(x);
  float h = 0.0;
  float acc = 1.0;   // the share of the tiles' height still showing
  {
    vec2 q = patchQ(uPG0, uPA0, mEN);
    float w = patchEdge(q, uPS0, uPG0, 40.0) * uPatchBlend * mix(1.0, uPatchGround, forTerrain) * (1.0 - smoothstep(4.0, 16.0, fpM / uPG0.z));
    if (w > 0.0) {
      float hv = patchHeightOne(uPH0, q, uPS0) + uPHOffset0;
      h = w * hv; acc = 1.0 - w;
    }
  }
  if (acc > 1e-3) h += acc * marchH(uvOf(x), lmin, lodG);
  return h;
}
// The same ground height from metres east and north of the site and the global map's uv (ground mode, src/ground/): no
// unit vector, so nothing is a 1.7 Mm quantity and the ground can be read to a millimetre.
float patchGroundEN(vec2 mEN, vec2 uv, float fpM, int lmin, float lodG) {
  float h = 0.0;
  float acc = 1.0;
  {
    vec2 q = patchQ(uPG0, uPA0, mEN);
    float w = patchEdge(q, uPS0, uPG0, 40.0) * uPatchBlend * uPatchGround * (1.0 - smoothstep(4.0, 16.0, fpM / uPG0.z));
    if (w > 0.0) {
      float hv = patchHeightOne(uPH0, q, uPS0) + uPHOffset0;
      h = w * hv; acc = 1.0 - w;
    }
  }
  if (acc > 1e-3) h += acc * marchH(uv, lmin, lodG);
  return h;
}


// Slopes (rise over run, east and north) of the ground at mEN: the patch levels' heights mixed coarse to fine.
// A level fades out only when a pixel is 4 to 16 of its texels (the coarsest never: far ground keeps its slope).
vec2 groundSlope(vec2 mEN, float fpM) {
  vec2 sl = vec2(0.0);
  {
    vec2 q = patchQ(uPG0, uPA0, mEN);
    float w = patchEdge(q, uPS0, uPG0, 40.0) * uPatchBlend;
    if (w > 0.0) sl = mix(sl, patchSlope(uPH0, q, uPS0, uPG0), w);
  }
  return sl;
}
// log2 of the image ratio at mEN, mixed coarse to fine (patchNormal's).
float groundDetail(vec2 mEN, float fpM) {
  float lr = 0.0;
  {
    vec2 q = patchQ(uPG0, uPA0, mEN);
    float w = patchEdge(q, uPS0, uPG0, 40.0) * uPatchBlend * (1.0 - smoothstep(8.0, 32.0, fpM / uPG0.z));
    if (w > 0.0) lr = mix(lr, patchDetail(uPR0, q, uPS0, uPG0, fpM), w);
  }
  return lr;
}


// ---- The frame (src/ground/frame.ts): metres east, north, up of the origin, float32-safe.
uniform vec3 uGCam;          // camera
uniform vec3 uGRight;        // camera basis in the frame
uniform vec3 uGUp;
uniform vec3 uGBack;
uniform float uGTanHalf;     // tangent of the vertical half-field
uniform vec3 uGSunL;         // Moon to Sun, unit, in the frame
uniform vec3 uGEarthL;       // Moon to Earth, unit, in the frame
uniform vec2 uGOff;          // the origin's metres east and north of the patch's site point
uniform float uGH0;          // ground height of the origin over the 1737.4 km sphere, metres
uniform float uGR;           // radius of the origin from the Moon's centre, metres
uniform vec2 uGUv0;          // the global maps' uv at the origin
uniform vec2 uGDuv;          // uv per metre east and per metre north (the second is negative: v runs south)
uniform vec3 uGSiteW;        // the origin's direction from the Moon's centre, world frame, unit
uniform float uGNear;        // the mesh camera's planes: the depth this pass writes is theirs
uniform float uGFar;
const float SUN_R = 0.267;
const float SUN_RAD = 0.267 * 0.017453292519943295;
const float G_MAXT = 60000.0;

float terrainH(vec2 en, float fpM) {
  float lmf = log2(max(1.0, fpM / (TH_KM * 1000.0)));
  int lm = clamp(int(floor(lmf + 0.5)), 0, 2);
  float lodG = log2(max(1.0, fpM / (TEXEL_KM * 1000.0)));
  return patchGroundEN(en + uGOff, uGUv0 + en * uGDuv, fpM, lm, lodG);
}
float terrainZ(vec2 en, float fpM) {
  return terrainH(en, fpM) - uGH0 - dot(en, en) / (2.0 * uGR);
}

// Where the ray o + t d meets the ground. hit: a crossing was found; else tMin is where the ray came closest
// (minAng: the angular clearance there, radians) and cover is the share of the pixel that closest approach covers.
struct GHit { float t; bool hit; float cover; float ang; };
float gGPxK = 1.0;   // the share of a pixel the ray stands for (1, or 1 / uHzK for a sub-pixel ray): the width of its coverage ramp
GHit groundHitRay(vec3 o, vec3 d) {
  float ta = 0.05, tb = 0.05;
  float minAng = 1e9, tMin = 0.05;
  bool hit = false;
  for (int i = 0; i < 384; i++) {
    vec3 x = o + d * tb;
    float c = x.z - terrainZ(x.xy, tb * uTanPerPx);
    if (c < 0.0) { hit = true; break; }
    float ang = c / tb;
    if (ang < minAng) { minAng = ang; tMin = tb; }
    ta = tb;
    if (tb >= G_MAXT) break;
    tb = min(G_MAXT, tb + max(c / (0.75 + abs(d.z)), 0.012 * tb + 0.02));
  }
  if (!hit) return GHit(tMin, false, clamp(0.5 - minAng / (uTanPerPx * gGPxK), 0.0, 1.0), minAng);
  for (int i = 0; i < 7; i++) {
    float tm = 0.5 * (ta + tb);
    vec3 x = o + d * tm;
    if (x.z < terrainZ(x.xy, tm * uTanPerPx)) tb = tm; else ta = tm;
  }
  return GHit(0.5 * (ta + tb), true, 1.0, 0.0);
}

// The skyline against the sky. Before, a ray that hit had coverage exactly 1 and one that missed a ramp from 0.5 to 0, so far ridges were a hard
// staircase. A far hit with sky one pixel above it, or a miss that cleared the ground by under a pixel and a half, is traced as uHzK sub-pixel rays
// stacked across the pixel on the world's vertical, and its coverage is their mean; t, hit and the shading are the centre ray's. A near hit, a miss
// well clear of the ground and any gesture frame cost what they did.
GHit groundHit(vec3 o, vec3 d) {
  gGPxK = 1.0;
  GHit g = groundHitRay(o, d);
  if (uHzK < 0.5 || uMotion > 0.5) return g;
  vec3 upv = vec3(0.0, 0.0, 1.0) - d * d.z;
  float ul = length(upv);
  if (ul < 0.05) return g;
  upv /= ul;
  if (g.hit) {
    if (g.t < 150.0) return g;
    if (groundHitRay(o, normalize(d + upv * uTanPerPx)).hit) return g;
  } else if (g.ang > 1.5 * uTanPerPx) return g;
  float k = min(uHzK, 8.0);
  gGPxK = 1.0 / k;
  float acc = 0.0;
  for (int i = 0; i < 8; i++) {
    if (float(i) >= k) break;
    acc += groundHitRay(o, normalize(d + upv * (((float(i) + 0.5) / k - 0.5) * uTanPerPx))).cover;
  }
  gGPxK = 1.0;
  g.cover = acc / k;
  return g;
}

// The share of the Sun's disc above the terrain's skyline from P: the smallest angular clearance of the ground
// along the ray to the Sun (0.3 m to 30 km, 20% steps), softened over the disc's radius, so the penumbra widens with
// the distance to the edge that casts it.
float sunVisibility(vec3 P, vec3 s, float t0) {
  float best = 1e9;
  float t = t0;
  float cosE = sqrt(max(1.0 - s.z * s.z, 0.0));
  for (int k = 0; k < 64; k++) {
    vec3 x = P + s * t;
    float c = x.z - terrainZ(x.xy, t * 0.004);
    best = min(best, c * cosE / t);
    t *= 1.2;
  }
  return smoothstep(-SUN_RAD, SUN_RAD, best);
}
// McEwen lunar-Lambert L(alpha), alpha in degrees (photometry.ts's twin), and the fitted phase function.
float lunarL(float a) {
  return max(0.0, 1.0 - 0.019 * a + 2.42e-4 * a * a - 1.46e-6 * a * a * a);
}
float phaseA(float a) { return exp(-0.0025 * a) * (1.0 + 0.9 * exp(-a / 20.0)) / 1.9; }

